{"cards": [{"node_code": "N_6e10bdda59a56e3a", "definition": "研究传统及常规变电站中基于微机保护、测控装置及后台监控系统的综合自动化架构，涵盖站控层、间隔层硬件配置、软件逻辑及就地控制策略。", "boundary": "本节点聚焦于非全数字化或混合架构变电站的自动化实现，核心在于微机装置的硬件选型、功能配置及站控层人机交互。若内容侧重于基于IEC61850标准的数字化通信模型、电子式互感器或智能终端技术，归入IEC61850标准与智能变电站节点；若仅讨论继电保护算法原理，归入继电保护节点。", "includes": ["变电站综合自动化系统硬件架构与微机保护/测控装置配置", "站控层监控系统软件、人机界面及数据管理", "常规变电站就地控制逻辑与操作票管理"], "excludes": ["基于IEC61850标准的数字化变电站通信模型与语义定义", "电子式互感器、合并单元及智能终端的具体硬件设计"], "sibling_distinctions": [{"other_code": "N_eaa727ec818f3254", "rule": "本节点侧重传统/常规变电站的微机控制架构与硬件实现；兄弟节点侧重基于IEC61850标准的数字化变电站体系、通信协议及智能设备集成。"}, {"other_code": "N_416958c3aeb574d7", "rule": "本节点侧重系统级的综合自动化架构与微机控制逻辑；兄弟节点侧重过程层中合并单元与智能终端的具体功能、接口及信号处理。"}], "cross_boundary_rule": "涉及微机保护装置时，若讨论其在综合自动化系统中的组网、通信接口及与站控层的交互归入本节点；若讨论其内部保护算法或整定归入继电保护节点。"}, {"node_code": "N_eaa727ec818f3254", "definition": "研究基于IEC61850国际标准构建的智能变电站体系，涵盖数字化一次设备、电子式互感器、过程层通信、逻辑节点建模及全站信息交互架构。", "boundary": "本节点聚焦于智能变电站的标准化体系与数字化特征，核心在于IEC61850标准的应用、逻辑节点定义、GOOSE/SV报文机制及全站一体化设计。若内容侧重于传统变电站的微机硬件架构，归入变电站综合自动化与微机控制节点；若仅讨论合并单元或智能终端的硬件电路，归入合并单元与智能终端节点。", "includes": ["IEC61850标准体系、逻辑节点建模及通信服务映射", "智能变电站三层两网架构、过程层通信及电子式互感器应用", "全站信息交互、智能设备集成及数字化一次设备接口"], "excludes": ["传统变电站基于RS485/CAN总线的微机控制架构", "合并单元与智能终端内部的具体硬件电路设计与信号调理"], "sibling_distinctions": [{"other_code": "N_6e10bdda59a56e3a", "rule": "本节点侧重基于IEC61850标准的数字化变电站体系与通信模型；兄弟节点侧重传统/常规变电站的微机控制架构与硬件实现。"}, {"other_code": "N_416958c3aeb574d7", "rule": "本节点侧重智能变电站整体架构、标准应用及信息交互逻辑；兄弟节点侧重过程层中合并单元与智能终端的具体设备功能与接口。"}], "cross_boundary_rule": "涉及智能变电站通信时，若讨论IEC61850标准模型、逻辑节点及报文机制归入本节点；若讨论具体通信硬件或物理层实现归入相关通信设备节点。"}, {"node_code": "N_416958c3aeb574d7", "definition": "研究智能变电站过程层中合并单元（MU）与智能终端（IT）的功能、接口、信号处理及与电子式互感器/断路器的交互技术。", "boundary": "本节点聚焦于过程层关键设备的硬件实现与信号交互，核心在于合并单元对模拟量的数字化采样、智能终端对开关量的采集与执行，以及二者与一次设备的接口。若内容侧重于IEC61850标准中的逻辑节点定义或全站通信架构，归入IEC61850标准与智能变电站节点；若侧重于保护算法，归入继电保护节点。", "includes": ["合并单元（MU）的采样、同步、数字化及接口技术", "智能终端（IT）的开关量采集、执行控制及与断路器交互", "过程层设备与电子式互感器、智能断路器的接口及信号处理"], "excludes": ["IEC61850标准中的逻辑节点建模与通信服务映射", "智能变电站整体架构设计及站控层/间隔层通信协议"], "sibling_distinctions": [{"other_code": "N_eaa727ec818f3254", "rule": "本节点侧重过程层中合并单元与智能终端的具体设备功能、硬件接口及信号处理；兄弟节点侧重智能变电站整体架构、IEC61850标准应用及信息交互逻辑。"}, {"other_code": "N_6e10bdda59a56e3a", "rule": "本节点侧重智能变电站过程层的关键设备（MU/IT）；兄弟节点侧重传统/常规变电站的微机控制架构与站控层系统。"}], "cross_boundary_rule": "涉及合并单元或智能终端时，若讨论其硬件设计、信号采样/执行、与一次设备接口归入本节点；若讨论其在IEC61850标准中的逻辑节点定义或通信报文归入IEC61850标准与智能变电站节点。"}]}
